# The pinned OTA helper names metadata from the signed OTA's pre-device
# property (XQ-DC72). Custota's update-info JSON contains only OTA/csig
# locations, so publish the same generated bytes under the ModOS device name.
set -o nounset -o pipefail -o errexit

source_path='XQ-DC72.json'
destination_path='pdx235.json'

[[ -f "${source_path}" && ! -L "${source_path}" && -s "${source_path}" ]] || {
  echo 'Error: generated XQ-DC72.json must be a nonempty regular file, not a symlink.' >&2
  exit 1
}

if [[ -e "${destination_path}" || -L "${destination_path}" ]]; then
  [[ -f "${destination_path}" && ! -L "${destination_path}" && -s "${destination_path}" ]] || {
    echo 'Error: existing pdx235.json is unsafe.' >&2
    exit 1
  }
  cmp -s -- "${source_path}" "${destination_path}" || {
    echo 'Error: existing pdx235.json differs from generated XQ-DC72.json.' >&2
    exit 1
  }
  echo 'Verified existing pdx235.json matches generated XQ-DC72.json.'
  exit 0
fi

temporary_path="$(mktemp './.pdx235.json.tmp.XXXXXX')"
cleanup() { rm -f -- "${temporary_path}"; }
trap cleanup EXIT

cp -- "${source_path}" "${temporary_path}"
cmp -s -- "${source_path}" "${temporary_path}" || {
  echo 'Error: copied pdx235.json does not match generated XQ-DC72.json.' >&2
  exit 1
}
mv -n -- "${temporary_path}" "${destination_path}"
trap - EXIT

[[ -f "${destination_path}" && ! -L "${destination_path}" && -s "${destination_path}" ]] &&
  cmp -s -- "${source_path}" "${destination_path}" || {
    echo 'Error: published pdx235.json failed post-copy verification.' >&2
    exit 1
  }

echo 'Prepared pdx235.json from verified XQ-DC72.json.'
